function fmtUsd(v: number | null | undefined, opts?: { dp?: number }): string {
  if (v === null || v === undefined || !Number.isFinite(v)) return "—";
  const dp = opts?.dp ?? 2;
  const sign = v < 0 ? "-" : "";
  const abs = Math.abs(v);
  return (
    sign +
    "$" +
    abs.toLocaleString("en-US", {
      minimumFractionDigits: dp,
      maximumFractionDigits: dp,
    })
  );
}

function fmtNum(v: number | null | undefined, dp: number = 4): string {
  if (v === null || v === undefined || !Number.isFinite(v)) return "—";
  return v.toLocaleString("en-US", {
    minimumFractionDigits: dp,
    maximumFractionDigits: dp,
  });
}

/** Compact USD formatter for big-notional figures (24h volume, open
 *  interest). Uses B / M / K suffixes so the value fits in a chart
 *  header without taking the space "1,234,567,890" would. */
function fmtUsdCompact(v: number | null | undefined): string {
  if (v === null || v === undefined || !Number.isFinite(v)) return "—";
  const abs = Math.abs(v);
  const sign = v < 0 ? "-" : "";
  if (abs >= 1e9) return `${sign}$${(abs / 1e9).toFixed(2)}B`;
  if (abs >= 1e6) return `${sign}$${(abs / 1e6).toFixed(2)}M`;
  if (abs >= 1e3) return `${sign}$${(abs / 1e3).toFixed(1)}K`;
  return `${sign}$${abs.toFixed(0)}`;
}

function timeAgo(ts: string): string {
  const ms = Date.now() - new Date(ts).getTime();
  if (ms < 1000) return "just now";
  if (ms < 60_000) return `${Math.floor(ms / 1000)}s ago`;
  return `${Math.floor(ms / 60_000)}m ago`;
}

/** Render a unix-ms timestamp as the operator's local "MM-DD HH:MM:SS". */
function fmtTime(ms: number, opts?: { withMs?: boolean }): string {
  if (!ms || !Number.isFinite(ms)) return "—";
  const d = new Date(ms);
  const mm = String(d.getMonth() + 1).padStart(2, "0");
  const dd = String(d.getDate()).padStart(2, "0");
  const hh = String(d.getHours()).padStart(2, "0");
  const mi = String(d.getMinutes()).padStart(2, "0");
  const ss = String(d.getSeconds()).padStart(2, "0");
  if (opts?.withMs) {
    const msPart = String(d.getMilliseconds()).padStart(3, "0");
    return `${mm}-${dd} ${hh}:${mi}:${ss}.${msPart}`;
  }
  return `${mm}-${dd} ${hh}:${mi}:${ss}`;
}

