/** v1.4.115 Phase 1E.1.b — regime_controller FSM mode + dwell +
 *  transition log payload. Mirrors
 *  ``app/regime_controller.py::snapshot_dict()`` plus a derived
 *  ``mode_since_iso`` (the publisher converts the monotonic dwell
 *  to a wall-clock ISO so the frontend can render
 *  ``Mode: DEFENSIVE · since 12:31:07`` directly). */
interface RegimeModeBlock {
  /** Phase 4G (v1.4.209) extended the FSM from 3 to 5 modes:
   *  "CALM" | "NORMAL" | "CAUTIOUS" | "DEFENSIVE" | "SHOCK" */
  mode: string;
  seconds_in_mode: number;
  mode_since_iso?: string;
  last_transition_reason: string | null;
  /** Non-null only while the FSM is arming a NORMAL → DEFENSIVE
   *  entry (15 s dwell). Shown as a small progress hint on the chip. */
  entry_arming_seconds: number | null;
  /** Non-null only while the FSM is arming a DEFENSIVE → NORMAL exit
   *  (30 s dwell). */
  exit_arming_seconds: number | null;
  transition_count: number;
  /** Most-recent-N transitions, newest-last. Each entry mirrors the
   *  Python tuple shape. */
  recent_transitions: Array<{
    from: string;
    to: string;
    ts_mono: number;
    /** Phase 4G.7 (v1.4.217) — wall-clock ISO 8601 timestamp
     *  derived from ``ts_mono`` + the snapshot's now-wall. Used by
     *  the dashboard regime band to plot transitions on the wall-
     *  clock X-axis. */
    ts_iso: string;
    reason: string;
  }>;
  time_in_normal_seconds: number;
  time_in_defensive_seconds: number;
  time_in_shock_seconds: number;
  /** Phase 4G.2 (v1.4.209) — CALM / CAUTIOUS session time counters
   *  and asymmetric-dwell arming timers (independent of the reactive
   *  entry/exit_arming_seconds above, which only cover the NORMAL ↔
   *  DEFENSIVE transition). Each `*_arming_seconds` is non-null only
   *  while the corresponding asymmetric dwell is actively counting.
   *  Default dwells: CAUTIOUS_ENTRY 3 s / CAUTIOUS_EXIT 60 s /
   *  CALM_ENTRY 120 s / CALM_EXIT 1 s. */
  time_in_calm_seconds: number;
  time_in_cautious_seconds: number;
  cautious_entry_arming_seconds: number | null;
  cautious_exit_arming_seconds: number | null;
  calm_entry_arming_seconds: number | null;
  calm_exit_arming_seconds: number | null;
  /** Phase 4G.5 (v1.4.211) — forward-classifier diagnostic block.
   *  Renders ALWAYS (per always-render contract); when the forward
   *  layer is disabled OR no reading yet, the inner fields are
   *  null / 0.0 placeholders. */
  forward_signal: {
    /** "CALM" | "NORMAL" | "CAUTIOUS" | null */
    classification: string | null;
    /** Human-readable string. CAUTIOUS reasons identify the dominant
     *  trigger (e.g. ``"vol_slope:1.20bp/min"``,
     *  ``"ob_widening:+0.45"``); NORMAL reasons identify the calm-
     *  failure tag (e.g. ``"not_calm:vol_high:5.20"``); CALM is
     *  ``"all_quiet"``. */
    reason: string | null;
    vol_slope_bps_per_min: number | null;
    drift_magnitude_30s_bps: number | null;
    drift_magnitude_rising_ratio_observed: number | null;
    ob_imbalance_widening_delta_observed: number | null;
    basis_stretch_ratio_observed: number | null;
    history_span_seconds: number;
  };
}

